    int zahl = int.Parse("zwölf");
    Console.WriteLine("Das wird nie ausgegeben");
}
catch (FormatException)
{
    Console.WriteLine("Das war keine gültige Zahl!");
}
Console.WriteLine("Programm läuft weiter");
// Ausgabe:
// Das war keine gültige Zahl!
// Programm läuft weiter

int[] noten = { 1, 2, 3 };
string[] eingaben = { "1", "abc", "7" };

foreach (string e in eingaben)
{
    try
    {
        int index = int.Parse(e);
        Console.WriteLine("Note: " + noten[index]);
    }
    catch (FormatException)
    {
        Console.WriteLine("Keine Zahl: " + e);
    }
    catch (IndexOutOfRangeException)
    {
        Console.WriteLine("Index zu groß: " + e);
    }
    catch (Exception ex)
    {
        Console.WriteLine("Unerwartet: " + ex.Message);
    }
}
// Ausgabe:
// Note: 2
// Keine Zahl: abc
// Index zu groß: 7

static int Teile(int a, int b)
{
    try
    {
        return a / b;
    }
    catch (DivideByZeroException)
    {
        Console.WriteLine("Division durch 0!");
        return 0;
    }
    finally
    {
        Console.WriteLine("fertig");
    }
}

Console.WriteLine(Teile(10, 2));
Console.WriteLine(Teile(1, 0));
// Ausgabe:
// fertig
// 5
// Division durch 0!
// fertig
// 0

static void SetzeNote(int note)
{
    if (note < 1 || note > 5)
    {
        throw new ArgumentException("Note muss zwischen 1 und 5 liegen");
    }
    Console.WriteLine("Note gespeichert: " + note);
}

try
{
    SetzeNote(2);
    SetzeNote(6);
}
catch (ArgumentException ex)
{
    Console.WriteLine("Fehler: " + ex.Message);
}
// Ausgabe:
// Note gespeichert: 2
// Fehler: Note muss zwischen 1 und 5 liegen

